function Base(id) {
  this.id = id;
}
Base.prototype.code = function () {
  return "B" + this.id;
};
function Sub(id) {
  Base.call(this, id);
}
Sub.prototype.early = () => "gone";
Sub.prototype = Object.create(Base.prototype);
Sub.prototype.constructor = Sub;
Sub.prototype.code = function () {
  return Base.prototype.code.call(this) + "-S";
};
const s = new Sub(3);
console.log(s.code());
console.log(typeof s.early);
console.log(Object.hasOwn(s, "id"));
console.log(s instanceof Base, s.constructor === Sub);
